def map_mut(fn):
 def m(r):
  p=r/'docs/implementation/IMPLEMENTATION-MAP.json';d=json.loads(p.read_text(encoding='utf-8'));fn(d);p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
